{
  "segment_function": "Examines the historical and philosophical tendency to escape the uncertainties of human action by substituting rule and making, tracing this movement from ancient tyranny to Plato's political philosophy.",
  "claims": [
    {
      "claim": "The calamities of action arise from the human condition of plurality, which constitutes the space of appearance in the public realm.",
      "claim_type": "author_position",
      "supporting_excerpt": "The calamities of action all arise from the human condition of plurality, which is the condition sine qua non for that space of appearance which is the public realm.",
      "support_kind": "direct",
      "confidence": 1.0
    },
    {
      "claim": "The traditional escape from the frailty of human affairs into rule rests on a deep suspicion of action and a desire to find a substitute for it.",
      "claim_type": "author_position",
      "supporting_excerpt": "The commonplace notion already to be found in Plato and Aristotle that every political community consists of those who rule and those who are ruled (on which assumption in turn are based the current definitions of forms of government—rule by one or monarchy, rule by few or oligarchy, rule by many or democracy) rests on a suspicion of action rather than on a contempt for men, and arose from the earnest desire to find a substitute for action rather than from any irresponsible or tyrannical will to power.",
      "support_kind": "direct",
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "plurality",
      "definition": "The human condition that serves as the condition sine qua non for the space of appearance which is the public realm, and from which the calamities of action arise."
    }
  ],
  "distinctions": [
    {
      "item_a": "archein (beginning)",
      "item_b": "prattein (achieving)",
      "distinction": "Plato opened a gulf between these two modes of action, which according to Greek understanding were originally interconnected, by dividing the beginner (ruler) from those who execute orders."
    }
  ]
}

